'use strict';

// MODULES //

var normalize = require( './normalize.js' );

/**
* Method to normalize the axis data.
*
* @private
* @name normalizeAxis
* @returns {void}
*/
function normalizeAxis() {
	var data;
	var frmt;
	var obj;
	var mxX;
	var mxZ;

	data = this._axisData.data;
	frmt = this._axisData.frmt;

	// X axis
	obj = normalize( data[ 0 ], frmt[ 0 ], 'graphemes' );
	mxX = obj.max;
	this._axisData[ 0 ] = obj;

	// Y axis
	obj = normalize( data[ 1 ], frmt[ 1 ], 'graphemes' );
	this._axisData[ 1 ] = obj;

	// Z Axis
	obj = normalize( data[ 2 ], frmt[ 2 ], 'graphemes' );
	mxZ = obj.max;
	this._axisData[ 2 ] = obj;

	// W axis
	obj = normalize( data[ 3 ], frmt[ 3 ], 'graphemes' );
	this._axisData[ 3 ] = obj;

	// Setting plot area
	this._plotArea.x = mxX;
	this._plotArea.y = 2;
	this._plotArea.z = this._plotAreaWidth + mxX;
	this._plotArea.w = 2 + this._plotAreaHeight + mxX;

	// Setting height and width for the matrix array

	// Axis tics space + plotAreaHeight
	this._height = 2 + 2 + this._plotAreaHeight;
	this._width = mxX + mxZ + this._plotAreaWidth;
}


// EXPORTS //

module.exports = normalizeAxis;
